```js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* env vars
const router = express.Router();

const MAX_LIMIT = 100;

const encodeCursor = (row) =>
  Buffer.from(JSON.stringify([row.cursor_ts, row.id])).toString('base64url');

function decodeCursor(cursor) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(cursor, 'base64url').toString());
    if (typeof ts !== 'string' || !['string', 'number'].includes(typeof id)) return null;
    return [ts, id];
  } catch {
    return null;
  }
}

router.get('/orders', async (req, res, next) => {
  const limit = req.query.limit === undefined ? 20 : Number(req.query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    return res.status(400).json({ error: `limit must be an integer from 1 to ${MAX_LIMIT}` });
  }

  let after = [];
  if (req.query.cursor !== undefined) {
    after = decodeCursor(req.query.cursor);
    if (!after) return res.status(400).json({ error: 'invalid cursor' });
  }

  try {
    // created_at::text keeps microseconds; a JS Date would truncate to ms and skip rows.
    // Fetch one extra row to know whether there is a next page.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
        ${after.length ? 'WHERE (created_at, id) < ($2::timestamptz, $3)' : ''}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      [limit + 1, ...after]
    );

    const page = rows.slice(0, limit);
    res.json({
      orders: page.map(({ cursor_ts, ...order }) => order),
      nextCursor: rows.length > limit ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    // Class 22 = bad data in a tampered cursor (malformed timestamp or id)
    if (err.code?.startsWith('22')) return res.status(400).json({ error: 'invalid cursor' });
    next(err);
  }
});

module.exports = router;
