```ts
export class JobQueue {
  private pending: Array<() => Promise<void>> = [];
  private active = 0;
  private idleWaiters: Array<() => void> = [];

  constructor(private concurrency: number, private retries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError('concurrency must be a positive integer');
    }
  }

  /** Resolves with the job's result, or rejects with its last error once retries run out. */
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(async () => {
        for (let attempt = 0; ; attempt++) {
          try {
            return resolve(await job());
          } catch (err) {
            if (attempt >= this.retries) return reject(err);
          }
        }
      });
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting. */
  onIdle(): Promise<void> {
    if (this.active === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private next(): void {
    while (this.active < this.concurrency && this.pending.length > 0) {
      // ponytail: shift() is O(n); swap in a linked list if the backlog reaches tens of thousands
      const run = this.pending.shift()!;
      this.active++;
      void run().then(() => {
        this.active--;
        this.next();
        if (this.active === 0 && this.pending.length === 0) {
          this.idleWaiters.splice(0).forEach((resolve) => resolve());
        }
      });
    }
  }
}
