import assert from 'node:assert/strict';
import { JobQueue } from './job-queue';

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

(async () => {
  const q = new JobQueue(2);
  let running = 0, maxRunning = 0, flakyCalls = 0, badCalls = 0;

  for (let i = 0; i < 5; i++) {
    void q.add(async () => {
      maxRunning = Math.max(maxRunning, ++running);
      await sleep(10);
      running--;
    });
  }
  const flaky = q.add(async () => {
    if (++flakyCalls < 3) throw new Error('flaky');
    return 'done';
  });
  const bad = q.add(async () => {
    badCalls++;
    throw new Error('always');
  });
  const badResult = bad.catch((e: Error) => e.message);

  await q.onIdle();
  assert.equal(maxRunning, 2);
  assert.equal(await flaky, 'done');
  assert.equal(await badResult, 'always');
  assert.equal(badCalls, 4); // 1 attempt + 3 retries
  console.log('ok');
})();
